**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int N, M;
    plik >> N >> M;

    vector<vector<int>> tab(N, vector<int>(M));
    for (int i = 0; i < N; i++)
        for (int j = 0; j < M; j++)
            plik >> tab[i][j];

    int maxRozstep = -1, maxWiersz = 0;
    for (int i = 0; i < N; i++) {
        int minW = tab[i][0], maxW = tab[i][0];
        for (int j = 1; j < M; j++) {
            if (tab[i][j] < minW) minW = tab[i][j];
            if (tab[i][j] > maxW) maxW = tab[i][j];
        }
        int rozstep = maxW - minW;
        cout << "Wiersz " << i + 1 << ": min=" << minW
             << ", max=" << maxW << ", rozstep=" << rozstep << endl;
        if (rozstep > maxRozstep) {
            maxRozstep = rozstep;
            maxWiersz = i;
        }
    }
    cout << "Najwiekszy rozstep: wiersz " << maxWiersz + 1
         << " (rozstep=" << maxRozstep << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Dla kazdego wiersza szukamy min i max (skan liniowy po kolumnach), obliczamy rozstep. Jednoczesnie sledzac globalny max rozstep.

Weryfikacja:
- Wiersz 1: min=7, max=45, rozstep=38
- Wiersz 2: min=48, max=52, rozstep=4
- Wiersz 3: min=3, max=99, rozstep=96
- Wiersz 4: min=20, max=25, rozstep=5
- Max rozstep: wiersz 3 z rozstepem 96.
